import{_ as p,a0 as i,w as d,s as r,I as o,a1 as a,A as e,x as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"開始使用 Roland 吧，一款命令列隨機選擇工具 | LCTT x X-CMD","titleTemplate":false,"description":"開始使用 Roland 吧，一款命令列隨機選擇工具 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開始使用 Roland 吧，一款命令列隨機選擇工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開始使用 Roland 吧，一款命令列隨機選擇工具 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190119 Get started with Roland, a random selection tool for the command line","title":"開始使用 Roland 吧，一款命令列隨機選擇工具","tag":"201902","desc":""},"relativePath":"201902/20190119 Get started with Roland, a random selection tool for the command line.md","filePath":"[post].md"}'),u={name:"201902/20190119 Get started with Roland, a random selection tool for the command line.md"};function m(f,s,g,c,k,h){const t=i("Link");return d(),r("div",null,[o("p",null,[a(t,{href:"collector:",title:"lujun9972"},{default:e(()=>[...s[0]||(s[0]=[n("#",-1)])]),_:1}),s[2]||(s[2]=n(": author: (Kevin Sonney ",-1)),a(t,{href:"https://opensource.com/users/ksonney"},{default:e(()=>[...s[1]||(s[1]=[n("https://opensource.com/users/ksonney",-1)])]),_:1}),s[3]||(s[3]=n(" (Kevin Sonney))",-1))]),s[24]||(s[24]=l('<h1 id="開始使用-roland-吧-一款命令列隨機選擇工具" tabindex="-1">開始使用 Roland 吧，一款命令列隨機選擇工具 <a class="header-anchor" href="#開始使用-roland-吧-一款命令列隨機選擇工具" aria-label="Permalink to “開始使用 Roland 吧，一款命令列隨機選擇工具”">​</a></h1><blockquote><p>Roland 可以幫你做出艱難的決定，它是我們在開源工具系列中的第七個工具，將幫助你在 2019 年提高工作效率。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/dice_tabletop_board_gaming_game.jpg?itok=y93eW7HN" alt=""></p><p>每年年初似乎都有瘋狂的衝動想提高工作效率。新年的決心，渴望開啓新的一年，當然，“拋棄舊的，擁抱新的”的態度促成了這一切。通常這時的建議嚴重偏向閉源和專有軟件，但事實上並不用這樣。</p><p>這是我挑選出的 19 個新的（或者對你而言新的）開源工具中的第七個工具來幫助你在 2019 年更有效率。</p><h3 id="roland" tabindex="-1">Roland <a class="header-anchor" href="#roland" aria-label="Permalink to “Roland”">​</a></h3><p>當一週的工作結束後，我唯一想做的就是躺到沙發上打一個週末的遊戲。但即使我的職業義務在工作日結束後停止了，但我仍然需要管理我的家庭。洗衣、寵物護理、確保我孩子有他所需要的東西，以及最重要的是：決定晚餐吃什麼。</p>',7)),o("p",null,[s[5]||(s[5]=n("像許多人一樣，我經常受到",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Decision_fatigue"},{default:e(()=>[...s[4]||(s[4]=[n("決策疲勞",-1)])]),_:1}),s[6]||(s[6]=n("的困擾，根據速度、準備難易程度以及（坦白地説）任何讓我壓力最小的方式都會導致不太健康的晚餐選擇。",-1))]),s[25]||(s[25]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/uploads/roland-1.png",alt:""})],-1)),o("p",null,[a(t,{href:"https://github.com/rjbs/Roland"},{default:e(()=>[...s[7]||(s[7]=[n("Roland",-1)])]),_:1}),s[8]||(s[8]=n(" 讓我計劃飯菜變得容易。Roland 是一款專為桌面角色扮演遊戲設計的 Perl 應用。它從怪物和僱傭者等項目列表中隨機挑選。從本質上講，Roland 在命令列做的事情就像遊戲管理員在桌子上擲骰子，以便在《要對玩家做的壞事全書》中找個東西一樣。",-1))]),s[26]||(s[26]=l(`<p>通過微小的修改，Roland 可以做得更多。例如，只需添加一張表，我就可以讓 Roland 幫我選擇晚餐。</p><p>第一步是安裝 Roland 及其依賴項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone git@github.com:rjbs/Roland.git</span></span>
<span class="line"><span>cpan install Getopt::Long::Descriptive Moose \\</span></span>
<span class="line"><span>   namespace::autoclean List:AllUtils Games::Dice \\</span></span>
<span class="line"><span>   Sort::ByExample Data::Bucketeer Text::Autoformat \\</span></span>
<span class="line"><span>   YAML::XS</span></span>
<span class="line"><span>cd oland</span></span></code></pre></div><p>接下來，創建一個名為 <code>dinner</code> 的 YAML 文檔，並輸入我們所有的用餐選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type: list</span></span>
<span class="line"><span>pick: 1</span></span>
<span class="line"><span>items:</span></span>
<span class="line"><span>  - &quot;frozen pizza&quot;</span></span>
<span class="line"><span>  - &quot;chipotle black beans&quot;</span></span>
<span class="line"><span>  - &quot;huevos rancheros&quot;</span></span>
<span class="line"><span>  - &quot;nachos&quot;</span></span>
<span class="line"><span>  - &quot;pork roast&quot;</span></span>
<span class="line"><span>  - &quot;15 bean soup&quot;</span></span>
<span class="line"><span>  - &quot;roast chicken&quot;</span></span>
<span class="line"><span>  - &quot;pot roast&quot;</span></span>
<span class="line"><span>  - &quot;grilled cheese sandwiches&quot;</span></span></code></pre></div><p>運行命令 <code>bin/roland dinner</code> 將讀取文件並選擇其中一項。</p><p><img src="https://opensource.com/sites/default/files/uploads/roland-2.png" alt=""></p><p>我想提前計劃一週，這樣我可以提前購買所有食材。 <code>pick</code> 命令確定列表中要選擇的物品數量，現在，<code>pick</code> 設置為 1。如果我想計劃一週的晚餐菜單，我可以將 <code>pick: 1</code> 變成 <code>pick: 7</code>，它會提供一週的菜單。你還可以使用 <code>-m</code> 選項手動輸入選擇。</p><p><img src="https://opensource.com/sites/default/files/uploads/roland-3.png" alt=""></p><p>你也可以用 Roland 做些有趣的事情，比如用經典短語添加一個名為 <code>8ball</code> 的文件。</p><p><img src="https://opensource.com/sites/default/files/uploads/roland-4.png" alt=""></p><p>你可以創建各種文件來幫助做出長時間工作後看起來非常難做的常見決策。即使你不用來做這個，你仍然可以用它來為今晚的遊戲設置哪個狡猾的陷阱做個決定。</p><hr>`,13)),o("p",null,[s[10]||(s[10]=n("via: ",-1)),a(t,{href:"https://opensource.com/article/19/1/productivity-tools-roland"},{default:e(()=>[...s[9]||(s[9]=[n("https://opensource.com/article/19/1/productivity-tools-roland",-1)])]),_:1})]),o("p",null,[s[15]||(s[15]=n("作者：",-1)),a(t,{href:"https://opensource.com/users/ksonney",title:"Kevin Sonney"},{default:e(()=>[...s[11]||(s[11]=[n("Kevin Sonney",-1)])]),_:1}),s[16]||(s[16]=n(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[12]||(s[12]=[n("lujun9972",-1)])]),_:1}),s[17]||(s[17]=n(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:e(()=>[...s[13]||(s[13]=[n("geekpi",-1)])]),_:1}),s[18]||(s[18]=n(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[n("wxy",-1)])]),_:1})]),o("p",null,[s[21]||(s[21]=n("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:e(()=>[...s[20]||(s[20]=[n("Linux中國",-1)])]),_:1}),s[23]||(s[23]=n(" 榮譽推出",-1))])])}const C=p(u,[["render",m]]);export{R as __pageData,C as default};
